// ============================================================
// 数学工具
// ============================================================
function nextPow2(n) {
    let p = 1;
    while (p < n) p <<= 1;
    return p;
}

function median(sorted) {
    const n = sorted.length;
    if (n === 0) return 0;
    return n % 2 ? sorted[(n - 1) >> 1]
                 : (sorted[n / 2 - 1] + sorted[n / 2]) / 2;
}

/** 去线性趋势（最小二乘），同时去掉直流 */
function detrend(arr) {
    const n = arr.length;
    let sx = 0, sy = 0, sxy = 0, sxx = 0;
    for (let i = 0; i < n; i++) {
        sx += i; sy += arr[i]; sxy += i * arr[i]; sxx += i * i;
    }
    const denom = n * sxx - sx * sx;
    const slope = denom !== 0 ? (n * sxy - sx * sy) / denom : 0;
    const intercept = (sy - slope * sx) / n;
    const out = new Float64Array(n);
    for (let i = 0; i < n; i++) out[i] = arr[i] - (slope * i + intercept);
    return out;
}

/** Hann 窗，抑制频谱泄漏 */
function applyHann(arr) {
    const n = arr.length;
    const out = new Float64Array(n);
    for (let i = 0; i < n; i++) {
        out[i] = arr[i] * 0.5 * (1 - Math.cos(2 * Math.PI * i / (n - 1)));
    }
    return out;
}

/** 原地基-2 Cooley-Tukey FFT，长度必须是 2 的幂 */
function fft(re, im) {
    const n = re.length;
    if (n <= 1) return;

    // 位反转置换
    for (let i = 1, j = 0; i < n; i++) {
        let bit = n >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) {
            [re[i], re[j]] = [re[j], re[i]];
            [im[i], im[j]] = [im[j], im[i]];
        }
    }

    for (let len = 2; len <= n; len <<= 1) {
        const ang = -2 * Math.PI / len;
        const wr = Math.cos(ang), wi = Math.sin(ang);
        for (let i = 0; i < n; i += len) {
            let cr = 1, ci = 0;
            for (let k = 0; k < len / 2; k++) {
                const ur = re[i + k], ui = im[i + k];
                const vr = re[i + k + len / 2] * cr - im[i + k + len / 2] * ci;
                const vi = re[i + k + len / 2] * ci + im[i + k + len / 2] * cr;
                re[i + k] = ur + vr;  im[i + k] = ui + vi;
                re[i + k + len / 2] = ur - vr;  im[i + k + len / 2] = ui - vi;
                const ncr = cr * wr - ci * wi;
                ci = cr * wi + ci * wr;
                cr = ncr;
            }
        }
    }
}

// ============================================================
// 启动
// ============================================================
window.addEventListener('DOMContentLoaded', () => {
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        showError('当前浏览器不支持摄像头访问。请使用 Chrome / Safari 等现代浏览器，' +
            '并通过 https 或 localhost 打开。');
        document.getElementById('btnStart').disabled = true;
        return;
    }
    // 不自动开启摄像头，等用户点击（移动端要求用户手势）
});

window.addEventListener('beforeunload', () => {
    if (state.stream) state.stream.getTracks().forEach(t => t.stop());
});

