const puppeteer = require('puppeteer-core');
const CHROME = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';

async function probe(headless) {
    const browser = await puppeteer.launch({
        executablePath: CHROME,
        headless,
        args: ['--use-fake-device-for-media-stream', '--use-fake-ui-for-media-stream',
               '--autoplay-policy=no-user-gesture-required', '--no-sandbox'],
    });
    const page = await browser.newPage();
    await page.goto('http://localhost:8199/', { waitUntil: 'domcontentloaded' }).catch(() => {});
    const r = await page.evaluate(async () => {
        try {
            const s = await navigator.mediaDevices.getUserMedia({ video: { width: 640, height: 480, frameRate: { ideal: 60 } } });
            const t = s.getVideoTracks()[0];
            return { ok: true, settings: t.getSettings() };
        } catch (e) {
            return { ok: false, name: e.name, message: e.message };
        }
    });
    console.log(`headless=${JSON.stringify(headless)} ->`, JSON.stringify(r));
    await browser.close();
}

const http = require('http');
const srv = http.createServer((_, res) => {
    res.writeHead(200, { 'Content-Type': 'text/html' });
    res.end('<html><body>probe</body></html>');
});
(async () => {
    await new Promise(r => srv.listen(8199, r));
    for (const h of ['shell', true, false]) {
        try { await probe(h); } catch (e) { console.log(`headless=${h} launch failed:`, e.message); }
    }
    srv.close();
})();

