/**
 * 采集看门狗。帧回调停止触发时（页面切后台、锁屏、掉流），
 * 到时间后强制收尾：样本够就出结果，不够就报错并复位。
 */
function armWatchdog(timeoutMs) {
    clearTimeout(state.watchdog);
    state.watchdog = setTimeout(() => {
        if (!state.running) return;
        if (state.timeSamples.length >= 16) {
            finishMeasure();
        } else {
